<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Purchase orders · ANERP</title><script src="https://cdn.tailwindcss.com"></script></head><body class="min-h-screen bg-slate-100 p-5 text-slate-900"><main class="mx-auto max-w-7xl space-y-6"><header class="flex items-center justify-between"><div><p class="text-sm text-slate-500">Procurement</p><h1 class="text-2xl font-bold">Purchase orders</h1></div><a href="{{ route('dashboard') }}" class="rounded-full bg-white px-4 py-2 shadow-sm">Dashboard</a><a href="{{ route('procurement.matching.index') }}" class="rounded-full bg-blue-600 px-4 py-2 text-white shadow-sm">Invoice matching</a></header>
