<section class="rounded-2xl bg-white p-5 shadow-sm"><h2 class="mb-4 font-semibold">Create purchase order draft</h2><form method="POST" action="{{ route('procurement.orders.store') }}" class="space-y-4">@csrf<div class="grid gap-3 md:grid-cols-4"><select name="supplier_id" required class="rounded-xl bg-slate-100 p-3"><option value="">Supplier</option>@foreach($suppliers as $s)<option value="{{ $s->id }}">{{ $s->code }} — {{ $s->name }}</option>@endforeach</select><select name="warehouse_id" required class="rounded-xl bg-slate-100 p-3"><option value="">Deliver to warehouse</option>@foreach($warehouses as $w)<option value="{{ $w->id }}">{{ $w->name }}</option>@endforeach</select><input type="date" name="order_date" required value="{{ now()->toDateString() }}" class="rounded-xl bg-slate-100 p-3"><input type="date" name="expected_date" class="rounded-xl bg-slate-100 p-3"></div><div class="flex items-center justify-between"><h3 class="font-semibold">Purchase order lines</h3><button type="button" id="add-po-line" class="rounded-full bg-slate-900 px-4 py-2 text-sm text-white">Add product line</button></div><div id="po-lines" class="space-y-2"><div class="grid gap-2 rounded-xl bg-slate-50 p-3 md:grid-cols-[2fr_1fr_1fr_auto] po-line"><select name="lines[0][product_id]" required class="rounded-xl bg-white p-3"><option value="">Product</option>@foreach($products as $p)<option value="{{ $p->id }}">{{ $p->sku }} — {{ $p->name }}</option>@endforeach</select><input name="lines[0][quantity]" required type="number" min="0.001" step="0.001" placeholder="Quantity" class="rounded-xl bg-white p-3"><input name="lines[0][unit_cost]" required type="number" min="0" step="0.01" placeholder="Unit cost (PGK)" class="rounded-xl bg-white p-3"><button type="button" class="remove-po-line rounded-full bg-white px-3 py-2 text-sm text-red-700 shadow-sm" disabled>Remove</button></div></div><input name="notes" placeholder="Notes / delivery instructions" class="w-full rounded-xl bg-slate-100 p-3"><button class="rounded-full bg-blue-600 px-6 py-3 font-semibold text-white">Save draft purchase order</button></form><template id="po-line-template"><div class="grid gap-2 rounded-xl bg-slate-50 p-3 md:grid-cols-[2fr_1fr_1fr_auto] po-line"><select name="lines[__INDEX__][product_id]" required class="rounded-xl bg-white p-3"><option value="">Product</option>@foreach($products as $p)<option value="{{ $p->id }}">{{ $p->sku }} — {{ $p->name }}</option>@endforeach</select><input name="lines[__INDEX__][quantity]" required type="number" min="0.001" step="0.001" placeholder="Quantity" class="rounded-xl bg-white p-3"><input name="lines[__INDEX__][unit_cost]" required type="number" min="0" step="0.01" placeholder="Unit cost (PGK)" class="rounded-xl bg-white p-3"><button type="button" class="remove-po-line rounded-full bg-white px-3 py-2 text-sm text-red-700 shadow-sm">Remove</button></div></template><script>document.addEventListener('DOMContentLoaded',()=>{const list=document.getElementById('po-lines'),tpl=document.getElementById('po-line-template'),add=document.getElementById('add-po-line');let next=1;add.addEventListener('click',()=>{const html=tpl.innerHTML.replaceAll('__INDEX__',String(next++));list.insertAdjacentHTML('beforeend',html);});list.addEventListener('click',e=>{const button=e.target.closest('.remove-po-line');if(button&&list.querySelectorAll('.po-line').length>1)button.closest('.po-line').remove();});});</script></section>
<section class="overflow-hidden rounded-2xl bg-white shadow-sm"><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-slate-500"><tr><th class="p-3">PO number</th><th class="p-3">Supplier</th><th class="p-3">Warehouse</th><th class="p-3">Date</th><th class="p-3 text-right">Total</th><th class="p-3">Status / actions</th></tr></thead><tbody>@forelse($orders as $o)<tr class="border-t align-top"><td class="p-3 font-semibold">{{ $o->order_number }}</td><td class="p-3">{{ $o->supplier?->name }}</td><td class="p-3">{{ $o->warehouse?->name }}</td><td class="p-3">{{ $o->order_date?->format('Y-m-d') }}</td><td class="p-3 text-right">K {{ number_format((float)$o->total,2) }}</td><td class="p-3"><div class="font-semibold capitalize">{{ str_replace('_',' ',$o->status) }}</div><div class="mt-2 flex flex-wrap gap-2">@if($o->status==='draft')<form method="POST" action="{{ route('procurement.orders.submit',$o->id) }}">@csrf<button class="rounded-full bg-blue-600 px-3 py-1.5 text-xs text-white">Submit</button></form>@elseif($o->status==='submitted')<form method="POST" action="{{ route('procurement.orders.approve',$o->id) }}">@csrf<button class="rounded-full bg-slate-900 px-3 py-1.5 text-xs text-white">Approve</button></form>@endif</div>
@if(in_array($o->status,['approved','partially_received']))<div class="mt-3 space-y-2">@foreach($o->lines as $line)<div class="rounded-lg bg-slate-50 p-2"><div class="text-xs">{{ $line->product?->name }} · received {{ number_format((float)$line->quantity_received,3) }} / {{ number_format((float)$line->quantity_ordered,3) }}</div><form method="POST" action="{{ route('procurement.orders.receive',[$o->id,$line->id]) }}" class="mt-2 flex gap-2">@csrf<input name="quantity" type="number" min="0.001" max="{{ (float)$line->quantity_ordered-(float)$line->quantity_received }}" step="0.001" required placeholder="Qty" class="w-24 rounded-lg bg-white p-2 text-xs"><button class="rounded-full bg-blue-600 px-3 py-1 text-xs text-white">Receive</button></form></div>@endforeach</div>@endif</td></tr>@empty<tr><td colspan="6" class="p-8 text-center text-slate-500">No purchase orders created.</td></tr>@endforelse</tbody></table></div><div class="p-4">{{ $orders->links() }}</div></section></main></body></html>
